import { Constants, StudioProApi } from "@mendix/extensions-api";

export const handleShowConstant = async (studioPro: StudioProApi, constantQualifiedName: string): Promise<void> => {
    const constant = await getConstantByQualifiedName(studioPro, constantQualifiedName);
    if (!constant) {
        const errorMessage = "Could not find constant.";
        const errorDetails =
            "This constant might have been deleted or renamed. Please update the tool constant selection.";
        return await studioPro.ui.messageBoxes.show("error", errorMessage, errorDetails);
    }
    await studioPro.ui.editors.editDocument(constant.$ID);
};

export const getConstantDefaultValue = (constant: Constants.Constant): string => {
    return constant?.defaultValue || "";
};

export const isStringConstant = (constant: Constants.Constant): boolean => {
    return constant?.type?.$Type === "DataTypes$StringType";
};

export const getConstantByQualifiedName = async (
    studioPro: StudioProApi,
    constantQualifiedName: string
): Promise<Constants.Constant | null> => {
    const [moduleName, constantName] = constantQualifiedName.split(".");
    if (!moduleName || !constantName) {
        return null;
    }
    const constants: Constants.Constant[] = await studioPro.app.model.constants.loadAll(
        (constant) => constant.moduleName === moduleName && constant.name === constantName
    );
    return constants.length > 0 ? constants[0] : null;
};
