import { useState, useEffect } from "react";

import { DocumentLookupResult, IComponent, StudioProApi } from "@mendix/extensions-api";

import { createDocumentEditorComponent } from "../utils/componentLoader";
import { PageContainer, PageContent } from "../components/PageContainers";
import AppThemeProvider from "../components/AppThemeProvider";
import { CenteredLoadingSpinner } from "../components/CenteredLoadingSpinner";

import { createNewConsumedMCPService, updateConsumedMCPServiceDocument } from "../../utils/consumedMCPServiceUtils";

import ConsumedMCPServiceEditor from "./consumedMCPServiceEditor";
import { ConsumedMCPService } from "../../types/consumedMCPService";

const initialMCPServiceDocument: ConsumedMCPService = createNewConsumedMCPService();

interface AppProps {
    studioPro: StudioProApi;
    documentId: string;
}

const App: React.FC<AppProps> = ({ studioPro, documentId }) => {
    const messageBoxApi = studioPro.ui.messageBoxes;
    const documentApi = studioPro.app.model.customBlobDocuments;
    const [isLoaded, setIsLoaded] = useState(false);
    const [consumedMCPService, setConsumedMCPService] = useState(initialMCPServiceDocument);

    useEffect(() => {
        documentApi
            .getDocumentById<ConsumedMCPService>(documentId)
            .then(async (documentFromModel: DocumentLookupResult<ConsumedMCPService>) => {
                if (documentFromModel && !("error" in documentFromModel)) {
                    const loadedConsumedMCPService = documentFromModel.document.contents;
                    setIsLoaded(true);
                    setConsumedMCPService(loadedConsumedMCPService);
                } else {
                    throw new Error(documentFromModel?.error || "Document not found");
                }
            })
            .catch(async (err) => {
                await messageBoxApi.show("error", "Error loading document", "Details: " + err?.message || err);
                setIsLoaded(true);
            });
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    return (
        <AppThemeProvider studioPro={studioPro}>
            <PageContainer>
                {!isLoaded && <CenteredLoadingSpinner />}
                {isLoaded && (
                    <PageContent>
                        <ConsumedMCPServiceEditor
                            loadedConsumedMCPService={consumedMCPService}
                            studioPro={studioPro}
                            updateStudioProDocument={updateConsumedMCPServiceDocument(studioPro, documentId)}
                        ></ConsumedMCPServiceEditor>
                    </PageContent>
                )}
            </PageContainer>
        </AppThemeProvider>
    );
};

export const component: IComponent = createDocumentEditorComponent(App);
